bool is_empty = pl.is_empty();

// Get point
Point pt = pl.get_point(1);

// Minimal and Full String Representation
std::string plstr = pl.str();
std::string plrepr = pl.repr();

// Copy (duplicates everything except guid)
Polyline plcopy = pl;
