// No-copy operators
Polyline plmult = pl;
plmult *= 2.0;
Polyline pldiv = pl;
pldiv /= 2.0;
Polyline pladd = pl;
pladd += Vector(1.0, 1.0, 1.0);
Polyline plsub = pl;
plsub -= Vector(1.0, 1.0, 1.0);

// Copy operators
Polyline rmul = pl * 2.0;
Polyline rdiv = pl / 2.0;
Polyline radd = pl + Vector(1.0, 1.0, 1.0);
Polyline rdif = pl - Vector(1.0, 1.0, 1.0);

